INSERT INTO news (type, crypto_category, news_title, news_text, effect_on_market, effect, version) VALUES 
('economic', 11, 'Рост спроса на IT-услуги в регионах', 'В регионах России активно растёт спрос на IT-услуги, такие как программирование, кибербезопасность и техподдержка. Это связано с развитием локальных технопарков и поддержкой государства. Какие компании могут получить выгоду от этого тренда, а где стоит проявить осторожность?', 60, true, 1),
('economic', 11, 'Спад спроса на IT-услуги в регионах', 'В регионах России активно снижается спрос на IT-услуги, такие как программирование, кибербезопасность и техподдержка. Это связано с замедлением развития локальных технопарков и сокращением поддержки государства. Какие компании могут пострадать от этого тренда, а где стоит проявить осторожность?', 60, false, 1),
('economic', 11, 'Расширение IT-парков в регионах', 'Государство инвестирует в новые IT-парки, стимулируя рост спроса на услуги. Компании в секторе ожидают бума.', 60, true, 1),
('economic', 11, 'Сокращение финансирования IT-парков', 'Государство сокращает инвестиции в IT-парки, приводя к спаду спроса на услуги. Компании в секторе в тревоге.', 60, false, 1),
('economic', 11, 'Бум кибербезопасности в регионах', 'Увеличение киберугроз приводит к росту спроса на услуги безопасности. IT-компании набирают обороты.', 60, true, 1),
('economic', 11, 'Спад интереса к кибербезопасности', 'Снижение киберугроз приводит к уменьшению спроса на услуги безопасности. IT-компании теряют клиентов.', 60, false, 1),
('economic', 12, 'Зеленые стандарты становятся обязательными', 'Правительство вводит новые требования экологической безопасности для промышленности. Производителям придется инвестировать в «чистые» технологии, что повысит затраты, но откроет рынок устойчивых продуктов. Стоит ли инвестировать в эко-проекты сейчас или подождать прояснения?', 55, true, 1),
('economic', 12, 'Зеленые стандарты становятся необязательными', 'Правительство смягчает требования экологической безопасности для промышленности. Производителям не придется инвестировать в «чистые» технологии, что снизит затраты, но закроет рынок устойчивых продуктов. Стоит ли избегать эко-проектов сейчас или подождать прояснения?', 55, false, 1),
('economic', 12, 'Государственные субсидии на эко-технологии', 'Новые субсидии стимулируют инвестиции в зеленые технологии, открывая новые рынки.', 55, true, 1),
('economic', 12, 'Отмена субсидий на эко-технологии', 'Отмена субсидий тормозит инвестиции в зеленые технологии, закрывая рынки.', 55, false, 1),
('economic', 12, 'Рост рынка устойчивых продуктов', 'Потребители предпочитают эко-продукты, повышая спрос и прибыли компаний.', 55, true, 1),
('economic', 12, 'Спад рынка устойчивых продуктов', 'Потребители игнорируют эко-продукты, снижая спрос и прибыли компаний.', 55, false, 1),
('economic', 13, 'Увеличение зарплат в строительной отрасли', 'Минимальная зарплата в строительстве выросла, что увеличивает издержки компаний и стоимость недвижимости. С другой стороны, спрос на жилье может возрасти из-за улучшения доходов строителей. Как это повлияет на сектор и связанные отрасли?', 50, true, 1),
('economic', 13, 'Снижение зарплат в строительной отрасли', 'Минимальная зарплата в строительстве снизилась, что уменьшает издержки компаний и стоимость недвижимости. С другой стороны, спрос на жилье может упасть из-за ухудшения доходов строителей. Как это повлияет на сектор и связанные отрасли?', 50, false, 1),
('economic', 13, 'Бум строительства жилых комплексов', 'Рост спроса на жилье приводит к буму в отрасли, увеличивая доходы.', 50, true, 1),
('economic', 13, 'Кризис в строительстве жилых комплексов', 'Спад спроса на жилье приводит к кризису в отрасли, уменьшая доходы.', 50, false, 1),
('economic', 13, 'Новые проекты инфраструктуры', 'Государственные проекты стимулируют рост в строительстве.', 50, true, 1),
('economic', 13, 'Отмена проектов инфраструктуры', 'Отмена государственных проектов тормозит рост в строительстве.', 50, false, 1),
('economic', 14, 'Снижение потребительской активности в секторе развлечений', 'Из-за экономической неопределенности люди стали реже тратить деньги на отдых и развлечения. Компании этой отрасли фиксируют падение доходов. Насколько этот спад окажется временным, а где — сигнал к переориентации?', 45, false, 1),
('economic', 14, 'Рост потребительской активности в секторе развлечений', 'Благодаря экономической стабильности люди стали чаще тратить деньги на отдых и развлечения. Компании этой отрасли фиксируют рост доходов. Насколько этот рост окажется постоянным, а где — сигнал к расширению?', 45, true, 1),
('economic', 14, 'Бум фестивалей и концертов', 'Рост интереса к живым событиям повышает доходы развлекательных компаний.', 45, true, 1),
('economic', 14, 'Спад в фестивалях и концертах', 'Снижение интереса к живым событиям уменьшает доходы развлекательных компаний.', 45, false, 1),
('economic', 14, 'Онлайн-развлечения набирают популярность', 'Платформы стриминга и игр видят рост аудитории.', 45, true, 1),
('economic', 14, 'Онлайн-развлечения теряют аудиторию', 'Платформы стриминга и игр фиксируют отток пользователей.', 45, false, 1),
('economic', 15, 'Рост инфляции в странах-партнерах', 'В валютных странах-партнерах отмечается рост инфляции, что ведет к удорожанию импорта и снижению рентабельности компаний, зависящих от зарубежных поставок. Какие отрасли окажутся наиболее уязвимы?', 70, false, 1),
('economic', 15, 'Снижение инфляции в странах-партнерах', 'В валютных странах-партнерах отмечается снижение инфляции, что ведет к удешевлению импорта и повышению рентабельности компаний, зависящих от зарубежных поставок. Какие отрасли окажутся наиболее выгодными?', 70, true, 1),
('economic', 15, 'Инфляция влияет на импорт', 'Высокая инфляция удорожает импортные товары, снижая прибыль.', 70, false, 1),
('economic', 15, 'Инфляция стабилизируется', 'Стабильная инфляция удешевляет импорт, повышая прибыль.', 70, true, 1),
('economic', 15, 'Глобальная инфляция замедляется', 'Мировая инфляция снижается, помогая экспортерам.', 70, true, 1),
('economic', 15, 'Глобальная инфляция ускоряется', 'Мировая инфляция растет, вредя экспортерам.', 70, false, 1),
('economic', 16, 'Появление новых технологий хранения энергии', 'Ведущие технологические компании объявляют о прорывах в аккумуляторных технологиях, что обещает снизить стоимость и повысить эффективность энергосбережения. Инвестиции в возобновляемую энергетику могут стать более привлекательными.', 65, true, 1),
('economic', 16, 'Задержка новых технологий хранения энергии', 'Ведущие технологические компании объявляют о задержках в аккумуляторных технологиях, что обещает увеличить стоимость и снизить эффективность энергосбережения. Инвестиции в возобновляемую энергетику могут стать менее привлекательными.', 65, false, 1),
('economic', 16, 'Прорыв в батареях для ЭМ', 'Новые батареи снижают стоимость электромобилей, стимулируя рынок.', 65, true, 1),
('economic', 16, 'Проблемы с батареями для ЭМ', 'Проблемы с батареями повышают стоимость электромобилей, тормозя рынок.', 65, false, 1),
('economic', 16, 'Рост возобновляемой энергетики', 'Инвестиции в солнечную энергию растут благодаря новым технологиям.', 65, true, 1),
('economic', 16, 'Спад возобновляемой энергетики', 'Инвестиции в солнечную энергию падают из-за задержек технологий.', 65, false, 1),
('economic', 17, 'Снижение ключевой ставки ожидается только через год', 'Центральные банки сигнализируют, что снижение ключевой ставки возможно не раньше следующего года, что сдерживает инвестиционную активность и рост рынка облигаций. Как это повлияет на долгосрочные и краткосрочные вложения?', 60, false, 1),
('economic', 17, 'Снижение ключевой ставки ожидается скоро', 'Центральные банки сигнализируют, что снижение ключевой ставки возможно скоро, что стимулирует инвестиционную активность и рост рынка облигаций. Как это повлияет на долгосрочные и краткосрочные вложения?', 60, true, 1),
('economic', 17, 'Стабилизация ставок', 'Стабильные ставки поддерживают кредитование бизнеса.', 60, true, 1),
('economic', 17, 'Рост ставок', 'Рост ставок замедляет кредитование бизнеса.', 60, false, 1),
('economic', 17, 'Ожидание снижения ставок', 'Ожидания снижения ставок повышают интерес к облигациям.', 60, true, 1),
('economic', 17, 'Задержка снижения ставок', 'Задержка снижения ставок снижает интерес к облигациям.', 60, false, 1),
('economic', 18, 'Активизация борьбы с финансовыми махинациями', 'Усиление мер по контролю и наказанию за мошенничество в финансовом секторе снижает риски инвесторов, но повсеместное ужесточение приводит к росту операционных затрат банков. Какие бизнес-модели выиграют от повышенной прозрачности?', 55, true, 1),
('economic', 18, 'Ослабление борьбы с финансовыми махинациями', 'Смягчение мер по контролю и наказанию за мошенничество в финансовом секторе увеличивает риски инвесторов, но сокращение ужесточения приводит к снижению операционных затрат банков. Какие бизнес-модели пострадают от снижения прозрачности?', 55, false, 1),
('economic', 18, 'Усиление контроля за скамом', 'Новые меры снижают риски, повышая доверие к рынку.', 55, true, 1),
('economic', 18, 'Слабый контроль за скамом', 'Слабые меры повышают риски, снижая доверие к рынку.', 55, false, 1),
('economic', 18, 'Прозрачность финансовых операций', 'Повышенная прозрачность привлекает инвесторов.', 55, true, 1),
('economic', 18, 'Снижение прозрачности финансовых операций', 'Сниженная прозрачность отпугивает инвесторов.', 55, false, 1),
('economic', 19, 'Регуляторные изменения для банков', 'Вводятся новые требования к ликвидности банковских учреждений. Это повысит надежность финансовой системы, но приведет к увеличению затрат банков и может сократить кредитование малого бизнеса. Опасайтесь ли вы замедления экономики?', 60, false, 1),
('economic', 19, 'Дерегуляция для банков', 'Смягчаются требования к ликвидности банковских учреждений. Это может снизить надежность финансовой системы, но приведет к уменьшению затрат банков и увеличению кредитования малого бизнеса. Оптимистичны ли вы по поводу экономического роста?', 60, true, 1),
('economic', 19, 'Новые требования к ликвидности', 'Требования повышают стабильность, но увеличивают затраты.', 60, false, 1),
('economic', 19, 'Смягчение требований к ликвидности', 'Смягчение снижает затраты, стимулируя кредиты.', 60, true, 1),
